package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** A claim made by a person on a sheet. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /** The date the claim is due by, fixed when it is added from the terms of its person's grade in
     *  force on its date; later changes to the terms or to the claim's date leave it as it is. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number, given when it is opened and kept once void; none while a draft. It is the
     *  sheet-wide 1, 2, ..., or while period numbering is in force <period name>-<n> or X-<n>. */
    @Column(name = "claim_number")
    private String number;

    /** What was due on the claim when it was settled; none while unsettled, or when no rate applied then. */
    @Column(name = "settled_due", precision = 12, scale = 2)
    private BigDecimal settledDue;

    /** Who opened the claim; none while a draft, or when voided without being opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Whether the person's last statement bound the claim to a figure; it then shows stated due. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the last statement bound the claim to; none when unbound, or when it was n/a then. */
    @Column(name = "stated_due", precision = 12, scale = 2)
    private BigDecimal statedDue;

    /** The number of the settled claim of the same person a correction (a negative amount) corrects; none otherwise. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's place in the sheet's list, which is newest first: the sheet's next place when it is
     *  added, and again when it is moved to another person. */
    @Column(name = "listed", nullable = false)
    private long listed;

    /** The date the claim is deferred until: while the sheet's today is before it an OPEN claim counts
     *  in no total, is not overdue, cannot be settled and no statement binds it; none when never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs the claim has had added. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number of the claim this one was split off from; none when it was not split off. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The claim's status log, oldest first: a line for each status it has had. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "position")
    private List<ClaimLogLine> log = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            int terms) {
        this.sheetId = sheetId;
        this.personId = personId;
        set(amount, date, note, corrects);
        this.dueBy = date.plusDays(terms);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public long getListed() {
        return listed;
    }

    public void setListed(long listed) {
        this.listed = listed;
    }

    /** Move the claim to another person, as their newest claim at the place given: it keeps its number
     *  and date, and loses any figure a statement bound it to, its due live again. */
    public void moveTo(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
        unbind();
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public String getNote() {
        return note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public List<ClaimLogLine> getLog() {
        return List.copyOf(log);
    }

    /** The status the claim had at the end of the day given, as its log records it; null when it was
     *  not yet added then. */
    public ClaimStatus statusAsOf(LocalDate date) {
        ClaimStatus then = null;
        for (ClaimLogLine line : log) if (!line.getOn().isAfter(date)) then = line.getStatus();
        return then;
    }

    /** The day the claim was last settled, as its log records it; null when it never was. */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogLine line : log) if (line.getStatus() == ClaimStatus.SETTLED) on = line.getOn();
        return on;
    }

    /** Log the claim's status now: who gave it, the sheet's today and its due (null: n/a) then. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogLine(status, by, on, due));
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getCorrects() {
        return corrects;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public boolean isStated() {
        return stated;
    }

    /** Whether the claim is bound to its stated figure now: stated, and not PENDING, as no statement
     *  binds a PENDING claim (its binding holds again should it be rejected). */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    /** Defer the claim until the date. */
    public void deferUntil(LocalDate until) {
        this.deferredUntil = until;
    }

    /** Whether the claim is deferred on the sheet's today: OPEN, with today before its deferred-until date. */
    public boolean isDeferredOn(LocalDate today) {
        return deferredUntil != null && status == ClaimStatus.OPEN && today != null && today.isBefore(deferredUntil);
    }

    public int getProofs() {
        return proofs;
    }

    /** Raise the claim's proofs count by one. */
    public void addProof() {
        proofs++;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    /** Split the amount given off the claim into a new OPEN claim of the same person, date and note,
     *  with the number given, opened by the user and due by the terms given from its date, split from
     *  this claim's number. This claim keeps the rest of its amount and loses any figure a statement
     *  bound it to. */
    public Claim splitOff(BigDecimal part, String number, String user, int terms) {
        Claim split = new Claim(sheetId, personId, part, date, note, null, terms);
        split.status = ClaimStatus.OPEN;
        split.number = number;
        split.openedBy = user;
        split.splitFrom = this.number;
        this.amount = amount.subtract(part).setScale(2);
        unbind();
        return split;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (null: n/a) as a statement takes it. */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Leave the claim unbound, its due live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }

    /** Change the claim's amount, date, note and the number it corrects; the amount is kept to two
     *  decimals, and only a correction keeps the number it corrects. */
    public void set(BigDecimal amount, LocalDate date, String note, String corrects) {
        this.amount = amount.setScale(2);
        this.date = date;
        this.note = note;
        this.corrects = isCorrection() ? corrects : null;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.TodayChanged;
import org.springframework.context.event.EventListener;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final PersonRepository people;
    private final SettingService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows,
            ClaimRepository claims, ClaimService claimService, PersonRepository people, SettingService settings,
            Audit audit) {
        this.settings = settings;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.claims = claims;
        this.claimService = claimService;
        this.people = people;
        this.audit = audit;
    }

    /** The sheet's periods in date order. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromAsc(sheetId);
    }

    /** Add a period, refused when its name is in use on the sheet, its to-date is before its
     *  from-date, or it shares a day with another of the sheet's periods. */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        sheets.load(sheetId);
        // Periods of a sheet are added one at a time, so two added at once cannot overlap.
        sheetRows.findForUpdate(sheetId);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
        }
        if (periods.existsBySheetIdAndNameKey(sheetId, Period.keyOf(name))) {
            throw nameInUse();
        }
        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps another period.");
        }
        Period saved;
        try {
            saved = periods.saveAndFlush(new Period(sheetId, name, from, to));
        } catch (DataIntegrityViolationException raced) {
            throw nameInUse();
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFrom() + " to=" + saved.getTo());
        return saved;
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month, each
     *  from the first to the last day of its month and named yyyy-mm; a blank date is the sheet's today.
     *  A month whose name is in use on the sheet, or whose days overlap one of its periods, is left out.
     *  Refused when the to-date is before the from-date. The periods made, in date order. */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        LocalDate today = sheets.today(sheetId);
        LocalDate start = from == null ? today : from;
        LocalDate end = to == null ? today : to;
        if (end.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
        }
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(start); !month.isAfter(YearMonth.from(end)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getNameKey().equals(Period.keyOf(name)) || p.overlaps(first, last))) {
                continue;
            }
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            existing.add(saved);
            made.add(saved);
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                    + " from=" + saved.getFrom() + " to=" + saved.getTo());
        }
        return made;
    }

    /** Close a period, fixing at this moment its due-total and each person's due-total for it: the figures as shown now of the claims
     *  dated in it that were open or settled at the end of its last day (by their status logs), skipping those that are n/a and the unbound open claims dated within a hold of their person, and the claims deferred on the sheet's today. Refused when the period is already closed, or the sheet's permission matrix does not allow the user's role to close. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        // Locked as claim changes lock it, so no claim in the period changes while it is closed.
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessPermitted(sheetId, user, "close", "Your role may not close a period on this sheet.");
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
        }
        return closeNow(sheetId, user, period, false);
    }

    /** Once the sheet's today is changed, close each open period whose to-date plus the sheet's grace days
     *  is before the new today, in order of their to-dates, as a close by hand would; none when the grace
     *  days are blank. Each is audited as closed automatically. */
    @EventListener
    @Transactional
    public void closeOverdue(TodayChanged change) {
        Integer grace = settings.graceDays(change.sheetId());
        if (grace == null) return;
        sheetRows.findForUpdate(change.sheetId());
        List<Period> due = periods.findBySheetIdOrderByFromAsc(change.sheetId()).stream()
                .filter((p) -> !p.isClosed() && p.getTo().plusDays(grace).isBefore(change.today()))
                .sorted(Comparator.comparing(Period::getTo)).toList();
        for (Period period : due) closeNow(change.sheetId(), change.user(), period, true);
    }

    /** Close an open period now, fixing its figures; the audit line marks a close the today change made. */
    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
        Map<Long, Person> peopleById = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        LocalDate today = sheets.today(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new HashMap<>();
        for (Long personId : peopleById.keySet()) personTotals.put(personId, BigDecimal.ZERO.setScale(2));
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = peopleById.get(claim.getPersonId());
            if (person == null) continue;
            // Counted by the status the claim had at the end of the period's last day; a hold only leaves
            // out a claim still open now, as holds touch only live claims.
            ClaimStatus then = claim.statusAsOf(period.getTo());
            boolean bound = claim.isStated() && then != ClaimStatus.PENDING;
            boolean counts = then != null && !claim.isDeferredOn(today) && (then == ClaimStatus.SETTLED
                    || (then.isOpen() && (bound || !claim.getStatus().isOpen() || !person.isHeldOn(claim.getDate()))));
            if (!counts || !period.contains(claim.getDate())) continue;
            BigDecimal due = claimService.due(sheetId, person, claim);
            if (due != null) {
                total = total.add(due);
                personTotals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        period.close(total, personTotals);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
        return saved;
    }

    /** Reopen a closed period, making its due-total live again. Refused when the sheet's permission
     *  matrix does not allow the user's role to reopen (by default, only a steward), or the period is not closed. */
    @Transactional
    public Period reopen(String sheetId, String user, long id) {
        // Locked as closing locks it, so a reopen and a close of the period do not cross.
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessPermitted(sheetId, user, "reopen", "Your role may not reopen a period on this sheet.");
        if (!period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on the sheet.");
    }
}

