247	        claim.addProof();
248	        Claim saved = claims.saveAndFlush(claim);
249	        recordChange("CLAIM_PROOF_ADDED", user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs());
250	        return saved;
251	    }
252	
253	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
254	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
255	     *  its new person's next statement). Refused unless the sheet's permission matrix allows the user's
256	     *  role to reassign (by default, a steward), and for a
257	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
258	     *  or to a person retired by the claim's date. */
259	    @Transactional
260	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
261	        Claim claim = claims.findForUpdate(id, sheetId)
262	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
263	        refuseIfClosed(sheetId, claim.getDate());
264	        settings.refuseUnlessPermitted(sheetId, user, "reassign",
265	                "Your role may not move a claim to another person on this sheet.");
266	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
267	            throw new ResponseStatusException(HttpStatus.CONFLICT,
268	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
269	        }
270	        Person from = person(sheetId, claim.getPersonId());
271	        Person to = person(sheetId, toPersonId);
272	        if (from.getId().equals(to.getId())) {
273	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
274	        }
275	        refuseIfRetired(to, claim.getDate());
276	        Rollup.Snapshot before = rollup.snapshot(sheetId);
277	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
278	        Claim saved = claims.saveAndFlush(claim);
279	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
280	                " from=" + from.getName() + " to=" + to.getName());
281	        rollup.recordChanges(user, before);
282	        return saved;
283	    }
284	
285	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
286	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
287	    @Transactional
288	    public Claim approve(String sheetId, String user, long id) {
289	        Claim claim = pending(sheetId, user, id);
290	        if (user.equals(claim.getOpenedBy())) {
291	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
292	                    "The user who opened a claim cannot approve it.");
293	        }
294	        Person person = person(sheetId, claim.getPersonId());
295	        BigDecimal dueNow = due(sheetId, person, claim);
296	        refuseIfUnproven(sheetId, claim, dueNow);
297	        Rollup.Snapshot before = rollup.snapshot(sheetId);
298	        claim.setStatus(ClaimStatus.SETTLED);
299	        claim.setSettledDue(dueNow);
300	        logStatus(sheetId, user, person, claim);
301	        Claim saved = claims.saveAndFlush(claim);
302	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
303	        notifyWatchers(user, person, saved);
304	        rollup.recordChanges(user, before);
305	        return saved;
306	    }
307	
308	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
309	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
310	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
311	    @Transactional
312	    public Claim resettle(String sheetId, String user, long id) {
313	        Claim claim = claims.findForUpdate(id, sheetId)
314	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
315	        refuseIfClosed(sheetId, claim.getDate());
316	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
317	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
318	        }
319	        if (claim.getStatus() != ClaimStatus.SETTLED) {
320	            throw new ResponseStatusException(HttpStatus.CONFLICT,
321	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
322	        }
323	        Person person = person(sheetId, claim.getPersonId());
324	        BigDecimal old = claim.getSettledDue();
325	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
326	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId),
327	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
328	        Rollup.Snapshot before = rollup.snapshot(sheetId);
329	        claim.setSettledDue(dueNow);
330	        logStatus(sheetId, user, person, claim);
331	        Claim saved = claims.saveAndFlush(claim);
332	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
333	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
334	        notifyWatchers(user, person, saved);
335	        rollup.recordChanges(user, before);
336	        return saved;
337	    }
338	
339	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
340	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
341	    @Transactional
342	    public Claim reject(String sheetId, String user, long id, String reason) {
343	        Claim claim = pending(sheetId, user, id);
344	        Person person = person(sheetId, claim.getPersonId());
345	        Rollup.Snapshot before = rollup.snapshot(sheetId);
346	        claim.setStatus(ClaimStatus.OPEN);
347	        logStatus(sheetId, user, person, claim);
348	        Claim saved = claims.saveAndFlush(claim);
349	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
350	        rollup.recordChanges(user, before);
351	        return saved;
352	    }
353	
354	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
355	     *  dated inside a closed period, or the user is not a steward of the sheet. */
356	    private Claim pending(String sheetId, String user, long id) {
357	        Claim claim = claims.findForUpdate(id, sheetId)
358	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
359	        refuseIfClosed(sheetId, claim.getDate());
360	        if (claim.getStatus() != ClaimStatus.PENDING) {
361	            throw new ResponseStatusException(HttpStatus.CONFLICT,
362	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
363	        }
364	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
365	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
366	        }
367	        return claim;
368	    }
369	
370	    /** How many days after its settlement a steward may still void a SETTLED claim. */
371	    private static final int VOID_SETTLED_DAYS = 7;
372	
373	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
374	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
375	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
376	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
377	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a settled claim.");
378	        }
379	        LocalDate settledOn = claim.settledOn();
380	        LocalDate today = sheets.today(sheetId);
381	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
382	            throw new ResponseStatusException(HttpStatus.CONFLICT,
383	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
384	        }
385	    }
386	
387	    /** The permission matrix's action for each status a claim is moved to by opening, settling or voiding it. */
388	    private static final Map<ClaimStatus, String> ACTIONS = Map.of(
389	            ClaimStatus.OPEN, "open", ClaimStatus.SETTLED, "settle", ClaimStatus.PENDING, "settle",
390	            ClaimStatus.VOID, "void");
391	
392	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
393	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
394	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
395	
396	    private static String text(BigDecimal due) {
397	        return due == null ? "n/a" : due.toPlainString();
398	    }
399	
400	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
401	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
402	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
403	    private String nextNumber(String sheetId, Claim claim) {
404	        LocalDate from = settings.periodNumberingFrom(sheetId);
405	        if (from == null || sheets.today(sheetId).isBefore(from)) {
406	            return Integer.toString(sheets.nextClaimNumber(sheetId));
407	        }
408	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
409	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
410	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
411	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
412	    }
413	
414	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
415	     *  in force on the claim's date (a due of n/a, or no threshold, needs none). */
416	    private void refuseIfUnproven(String sheetId, Claim claim, BigDecimal due) {
417	        if (due == null || claim.getProofs() > 0) return;
418	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
419	        if (threshold != null && due.compareTo(threshold) > 0) {
420	            throw new ResponseStatusException(HttpStatus.CONFLICT,
421	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
422	                            + "; add a proof before it is settled.");
423	        }
424	    }
425	
426	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
427	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
428	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
429	        BigDecimal limit = settings.clerkLimit(sheetId);
430	        return limit != null && due.compareTo(limit) > 0;
431	    }
432	
433	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
434	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
435	    private void refuseIfClosed(String sheetId, LocalDate date) {
436	        sheetRows.findForUpdate(sheetId);
437	        if (periods.isClosedOn(sheetId, date)) {
438	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
439	        }
440	    }
441	
442	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
443	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
444	        if (amount.signum() >= 0) return;
445	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
446	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
447	        if (!settled) {
448	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
449	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
450	        }
451	    }
452	
453	    /** Refuse a claim dated after its person's retirement date. */
454	    private static void refuseIfRetired(Person person, LocalDate date) {
455	        if (person.isRetiredOn(date)) {
456	            throw new ResponseStatusException(HttpStatus.CONFLICT,
457	                    "The claim is dated after " + person.getName() + " retired.");
458	        }
459	    }
460	
461	    private Person person(String sheetId, long personId) {
462	        return people.findByIdAndSheetId(personId, sheetId)
463	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
464	    }
465	
466	    /** What is due on the claim now: the due fixed when it was settled, else the greater of the floor in
467	     *  force on its date and its figure with the late charge on top while it is open and overdue (the charge
468	     *  is never bound by a statement; a correction has no floor); null when the figure is n/a. */
469	    public BigDecimal due(String sheetId, Person person, Claim claim) {
470	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), settings.floor(sheetId, claim.getDate()),
471	                sheets.today(sheetId),
472	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
473	    }
474	
475	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
476	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
477	     *  null when that is n/a. */
478	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
479	        if (claim.getSettledDue() != null) return claim.getSettledDue();
480	        if (claim.isBound()) return claim.getStatedDue();
481	        return dueNow(sheetId, person, claim);
482	    }
483	
484	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
485	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
486	     *  floor; null when no rate of the grade applies by then. */
487	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
488	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
489	        if (rate == null) return null;
490	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
491	                rounding(sheetId, claim));
492	    }
493	
494	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
495	     *  correction corrects, else by its own. */
496	    private RoundingMode rounding(String sheetId, Claim claim) {
497	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
498	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
499	                : null;
500	        return Rounding.of(Rounding.dateOf(claim, corrected),
501	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
502	    }
503	
504	    /** Log the status the claim has just taken, with its due as worked out now. */
505	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
506	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
507	    }
508	
509	    private void recordChange(String event, String user, Person person, Claim claim) {
510	        recordChange(event, user, person, claim, claim.getNumber(), "");
511	    }
512	
513	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
514	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
515	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
516	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
517	                + (number == null ? "" : " number=" + number) + extra);
518	    }
519	
520	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
521	    private void notifyWatchers(String user, Person person, Claim claim) {
522	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
523	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
524	                    + " person=" + person.getName() + " number=" + claim.getNumber());
525	        }
526	    }
527	
528	    private LocalDate dateOr(String sheetId, LocalDate date) {
529	        return date != null ? date : sheets.today(sheetId);
530	    }
531	
532	    private static String noteOf(String note) {
533	        return note == null ? "" : note.trim();
534	    }
535	}
